'use client';

/**
 * @file index.ts
 * @input Imports from Toolbar component files
 * @output Exports Toolbar and types
 * @position Entry point for Toolbar module
 *
 * SYNC: When modified, update /packages/core/src/Toolbar/Toolbar.doc.mjs
 */

export {Toolbar} from './Toolbar';
export type {ToolbarProps, ToolbarSize} from './Toolbar';

// Copyright (c) Meta Platforms, Inc. and affiliates.

/**
 * @file focusableSelector.ts
 * @input None (a plain CSS selector string constant)
 * @output Exports FOCUSABLE_SELECTOR, isDisabledWithin and preferTabStops
 * @position Internal utility; the canonical CSS selector for focusable
 *   elements, shared by focus-management hooks (e.g. useFocusTrap) so the
 *   selector isn't duplicated across components/hooks. Not exported from the
 *   public barrel — internal implementation detail.
 */

/**
 * Canonical CSS selector for commonly focusable elements. Includes the
 * tabbable natives (button/link/input/select/textarea/[tabindex]) plus
 * editable and media elements the browser also puts in the tab order —
 * contenteditable, media with controls, iframe, and an open <details>'s
 * <summary> — which a naive selector misses, letting Tab escape a trap whose
 * only interactive content is (e.g.) a contenteditable composer (infra-8).
 *
 * This is the canonical focusable selector; prefer importing it here over
 * re-declaring the string so behavior stays consistent across hooks.
 */
export const FOCUSABLE_SELECTOR =
  'button:not([disabled]), a[href], area[href], input:not([disabled]), select:not([disabled]), textarea:not([disabled]), [tabindex]:not([tabindex="-1"]):not([disabled]), [contenteditable]:not([contenteditable="false"]), audio[controls], video[controls], iframe, details > summary:first-child';

/**
 * Whether `element` is disabled inside `container`: it, or an ancestor up to
 * `container`, has `aria-disabled="true"`. Popover skips such an element when
 * it picks initial focus. Tab still reaches it.
 */
export function isDisabledWithin(
  element: Element,
  container: Element,
): boolean {
  const disabled = element.closest('[aria-disabled="true"]');
  return disabled != null && container.contains(disabled);
}

/**
 * `elements` with tab stops first, each group in document order. Inside a
 * composite widget with a roving tab stop (a grid, a toolbar), the member
 * that holds `tabindex="0"` comes before the members that hold `-1`.
 */
export function preferTabStops<T extends Element>(
  elements: ReadonlyArray<T>,
): T[] {
  const isTabStop = (element: T) => element.getAttribute('tabindex') !== '-1';
  return [
    ...elements.filter(isTabStop),
    ...elements.filter(element => !isTabStop(element)),
  ];
}

// Copyright (c) Meta Platforms, Inc. and affiliates.

'use client';

/**
 * @file isRtlElement.ts
 * @input DOM element (nullable)
 * @output Exports isRtlElement helper resolving an element's computed text
 *   direction
 * @position Internal hook utility; used by useListFocus and useGridFocus to
 *   auto-detect RTL for arrow-key navigation (same getComputedStyle precedent
 *   as Resizable's ResizeHandle drag deltas).
 */

/**
 * Whether `el` renders right-to-left, per its computed `direction`.
 *
 * SSR-safe: returns false when `el` is null or no DOM is available. Callers
 * should invoke this lazily (on keydown, not on render) so getComputedStyle
 * runs only when a horizontal arrow key is actually handled.
 */
export function isRtlElement(el: HTMLElement | null): boolean {
  if (!el || typeof window === 'undefined') {
    return false;
  }
  return window.getComputedStyle(el).direction === 'rtl';
}

// Copyright (c) Meta Platforms, Inc. and affiliates.

'use client';

/**
 * @file useAttachment.ts
 * @input Node refs (an element's, or the document's), an attach function
 *   and a key
 * @output Exports useAttachment and useAttachmentPair (two elements): they keep
 *   the attach function bound to the nodes the refs hold across commits
 * @position Internal React helper, not in hooks/index.ts: the one attach and
 *   release lifecycle of the gesture hooks, the pager and useAnimator
 *
 * SYNC: When modified, update gestures/__tests__/useGestureRecognizer.test.tsx,
 * gestures/__tests__/useFingerScroll.test.tsx and
 * __tests__/useAttachmentPair.test.tsx.
 */

import {useRef, type RefObject} from 'react';
import {useIsomorphicLayoutEffect} from './useIsomorphicLayoutEffect';

/**
 * Keep `attach` bound to the node `ref` holds after each commit: an element,
 * or the document. A replaced node is released and the new one attached, a
 * changed `key` re-attaches, and the last attachment is released on unmount;
 * a commit that changes neither does nothing (react-component-runtime INV3).
 */
export function useAttachment<T extends Node = Element>(
  ref: RefObject<T | null>,
  attach: (element: T) => () => void,
  key: unknown,
): void {
  useAttachedNodes([ref], ([node]) => attach(node as T), key);
}

/**
 * `useAttachment` for two elements. It keeps `attach` bound to the pair the
 * refs hold after each commit, once both are there. Replacing either element
 * releases the attachment and attaches the new pair. A changed `key`
 * re-attaches, and the last attachment is released on unmount. A commit that
 * changes neither does nothing.
 */
export function useAttachmentPair<A extends Element, B extends Element>(
  firstRef: RefObject<A | null>,
  secondRef: RefObject<B | null>,
  attach: (first: A, second: B) => () => void,
  key: unknown,
): void {
  useAttachedNodes(
    [firstRef, secondRef],
    ([first, second]) => attach(first as A, second as B),
    key,
  );
}

/**
 * The lifecycle both share: one attachment of the nodes the refs hold. It is
 * made once every node is there, and released when a node or `key` changes
 * and at unmount.
 */
function useAttachedNodes(
  refs: ReadonlyArray<RefObject<Node | null>>,
  attach: (nodes: ReadonlyArray<Node>) => () => void,
  key: unknown,
): void {
  const attachmentRef = useRef<{
    nodes: ReadonlyArray<Node>;
    key: unknown;
    release: () => void;
  } | null>(null);

  // Syncs the attachment with the DOM nodes the refs hold after this commit.
  useIsomorphicLayoutEffect(() => {
    const nodes = refs.map(ref => ref.current);
    const current = attachmentRef.current;
    if (
      current != null &&
      current.key === key &&
      nodes.every((node, index) => node === current.nodes[index])
    ) {
      return;
    }
    current?.release();
    attachmentRef.current = nodes.every(node => node != null)
      ? {
          nodes: nodes,
          key,
          release: attach(nodes),
        }
      : null;
  });

  // Releases the attachment at unmount.
  useIsomorphicLayoutEffect(
    () => () => {
      attachmentRef.current?.release();
      attachmentRef.current = null;
    },
    [],
  );
}

